import{_ as t,o as n,c as a,a5 as s}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"AI Architecture — ai-service Internal Design","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/ai-service-architecture.md","filePath":"architecture/ai-service-architecture.md"}'),i={name:"architecture/ai-service-architecture.md"};function c(r,e,o,d,l,p){return n(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="ai-architecture-—-ai-service-internal-design" tabindex="-1">AI Architecture — ai-service Internal Design <a class="header-anchor" href="#ai-architecture-—-ai-service-internal-design" aria-label="Permalink to &quot;AI Architecture — ai-service Internal Design&quot;">​</a></h1><p>&gt; DA-1158 (DA-E05-07). Nguồn: <code>docs/ba/06-ai-features.md</code>, <code>docs/ba/use-cases/05-ai-features.md</code>, <code>docs/database/schema-v2/brandhub-dbml.dbml</code>.</p><h2 id="_1-internal-architecture-fastapi" tabindex="-1">1. Internal Architecture (FastAPI) <a class="header-anchor" href="#_1-internal-architecture-fastapi" aria-label="Permalink to &quot;1. Internal Architecture (FastAPI)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ai-service/</span></span>
<span class="line"><span>├── routers/          # FastAPI route handlers, 1 file per feature group</span></span>
<span class="line"><span>│   ├── caption.py         (UC-75)</span></span>
<span class="line"><span>│   ├── ambassador.py      (UC-76)</span></span>
<span class="line"><span>│   ├── image.py           (UC-77)</span></span>
<span class="line"><span>│   ├── video.py           (UC-78, async job pattern)</span></span>
<span class="line"><span>│   ├── trending.py        (UC-74, UC-80 crawl config)</span></span>
<span class="line"><span>│   ├── livestream.py      (UC-81)</span></span>
<span class="line"><span>│   └── collaborator.py    (UC-82)</span></span>
<span class="line"><span>├── services/          # business logic, tách khỏi router</span></span>
<span class="line"><span>│   ├── llm_router.py       # chọn model theo task type</span></span>
<span class="line"><span>│   ├── prompt_builder.py   # ghép form + ambassador + materials → prompt</span></span>
<span class="line"><span>│   ├── credit_reporter.py  # ghi ai_usage_logs sau mỗi lần generate</span></span>
<span class="line"><span>│   └── rag_service.py      # ChromaDB retrieval cho brand voice</span></span>
<span class="line"><span>├── clients/            # external API clients</span></span>
<span class="line"><span>│   ├── groq_client.py</span></span>
<span class="line"><span>│   ├── stability_client.py</span></span>
<span class="line"><span>│   └── veo_client.py</span></span>
<span class="line"><span>└── tasks/              # async job handling (video-gen)</span></span>
<span class="line"><span>    └── video_job_worker.py    # background task, poll-based status</span></span></code></pre></div><ul><li><strong>Async task handling:</strong> video-gen job chạy nền qua FastAPI <code>BackgroundTasks</code> (hoặc Celery nếu volume tăng — chưa cần ở giai đoạn hiện tại), trạng thái lưu tạm trong <code>ai_usage_logs</code>/in-memory job store, client poll <code>GET /internal/ai/video/{jobId}/status</code>.</li><li><strong>Service layer tách khỏi router:</strong> router chỉ parse request/validate input, gọi <code>services/*</code> — giữ router mỏng, dễ test logic độc lập.</li></ul><h2 id="_2-chromadb-schema" tabindex="-1">2. ChromaDB Schema <a class="header-anchor" href="#_2-chromadb-schema" aria-label="Permalink to &quot;2. ChromaDB Schema&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Mô tả</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>UUID của document/chunk</td></tr><tr><td><code>embedding</code></td><td>vector</td><td>Sinh từ sentence-transformers (model cấu hình qua env, không hardcode)</td></tr><tr><td><code>metadata.agencyId</code></td><td>string</td><td><strong>Cấp cô lập chính (V2)</strong> — không phải <code>workspaceId</code></td></tr><tr><td><code>metadata.workspaceId</code></td><td>string | null</td><td>Optional — brand voice có thể áp dụng riêng theo Workspace nếu Agency cấu hình khác nhau giữa các Workspace</td></tr><tr><td><code>metadata.sourceType</code></td><td>string</td><td><code>brand_document</code> | <code>material_description</code> | <code>hashtag_history</code></td></tr><tr><td><code>metadata.createdAt</code></td><td>ISO 8601</td><td>Thời điểm index</td></tr></tbody></table><h3 id="collection-naming-convention-sua-so-voi-ban-v1-cu" tabindex="-1">Collection naming convention (SỬA so với bản V1 cũ) <a class="header-anchor" href="#collection-naming-convention-sua-so-voi-ban-v1-cu" aria-label="Permalink to &quot;Collection naming convention (SỬA so với bản V1 cũ)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agency_{agencyId}_brand_voice</span></span></code></pre></div><p><strong>Lý do đổi từ <code>workspace_{workspaceId}_brand_voice</code> (V1) sang cấp Agency:</strong> AI credit và brand voice knowledge trong V2 gắn với <strong>Agency</strong> (1 Owner quản lý credit chung cho toàn Agency, có thể set hạn mức riêng từng Creator — xem <code>docs/ba/08-subscription-billing.md</code>), không phải từng Workspace lẻ. Một Agency có nhiều Workspace (nhiều Client) nhưng brand voice tổng quát của Agency (giọng văn, phong cách) có thể dùng chung — Workspace cụ thể chỉ cần lọc thêm qua <code>metadata.workspaceId</code> khi Client đó có brand riêng biệt cần tách.</p><ul><li><strong>top-K retrieval:</strong> 5 (mặc định cho RAG context injection vào prompt).</li></ul><h2 id="_3-llm-routing-strategy" tabindex="-1">3. LLM Routing Strategy <a class="header-anchor" href="#_3-llm-routing-strategy" aria-label="Permalink to &quot;3. LLM Routing Strategy&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task type</th><th>Model/Endpoint</th><th>UC</th></tr></thead><tbody><tr><td>Caption/Text generation</td><td>Groq LLaMA (model ID qua config, không hardcode — vd <code>llama3-8b-8192</code>)</td><td>UC-75</td></tr><tr><td>RAG (brand voice retrieval + generation)</td><td>Groq + ChromaDB retrieval trước khi gửi prompt</td><td>UC-74 (trending), context injection cho UC-75/77/78</td></tr><tr><td>Image generation</td><td>Stability AI, LoRA fine-tune tùy chỉnh theo brand</td><td>UC-77</td></tr><tr><td>Video generation</td><td>Google Veo hoặc third-party API tương đương</td><td>UC-78</td></tr><tr><td>Livestream script</td><td>Groq LLaMA, cùng pipeline với Caption</td><td>UC-81</td></tr><tr><td>Recommend Collaborator</td><td>Groq LLaMA, không cần RAG (không phụ thuộc brand voice riêng)</td><td>UC-82</td></tr></tbody></table><ul><li><strong>Config, không hardcode:</strong> model ID/endpoint đọc từ biến môi trường (<code>GROQ_MODEL_ID</code>, <code>STABILITY_API_KEY</code>, <code>VEO_API_ENDPOINT</code>) — cho phép swap model không cần sửa code, chỉ đổi config khi cần nâng cấp/hạ cấp chất lượng vs chi phí.</li></ul><h2 id="_4-credit-accounting-lien-ket-business-service" tabindex="-1">4. Credit Accounting (liên kết business-service) <a class="header-anchor" href="#_4-credit-accounting-lien-ket-business-service" aria-label="Permalink to &quot;4. Credit Accounting (liên kết business-service)&quot;">​</a></h2><ul><li>ai-service tự ghi <code>ai_usage_logs</code> (MongoDB, ai-service sở hữu) sau MỖI lần generate thành công — dùng cho audit/debug, không phải nguồn số dư chính.</li><li>Số dư credit thật (<code>ai_credit_ledgers</code>) và hạn mức từng Creator (<code>ai_credit_creator_limits</code>) nằm ở PostgreSQL, business-service sở hữu — business-service kiểm tra TRƯỚC khi gọi ai-service, trừ credit SAU khi ai-service trả kết quả (xem <code>docs/architecture/business-ai-rest-contract.md</code> §6).</li><li>Tái sử dụng asset đã generate trước đó (UC-79 Export) <strong>không</strong> trừ credit lần 2 — FR 3.6.35.</li></ul>`,16)])])}const u=t(i,[["render",c]]);export{g as __pageData,u as default};
